<template>
  <section ref="root" class="procurement-forecast" v-loading="loading">
    <div class="heading"><div><span class="eyebrow">02 · 采购情景推演 · 2026 Q4</span><h2>130 tU采购方案 · 每日库存与交付推演</h2><p>决策日2026年10月22日 · 天然铀精矿U₃O₈ · 数量统一按金属铀含量tU</p></div><span class="case-badge">详细案例计算</span></div>
    <div v-if="error" class="load-error">{{ error }} <el-button size="small" @click="load">重试</el-button></div>
    <template v-if="data">
      <div class="case-inputs"><div class="case-section-label">案例输入与公开指标</div><div class="facts"><div v-for="fact in facts" :key="fact.label"><span>{{ fact.label }}</span><strong>{{ fact.value }}<small>{{ fact.unit }}</small></strong></div></div>
      <p class="formula">{{ data.formula }}</p><div v-if="data.public_evidence" class="market-context"><article v-for="item in data.public_evidence.records.filter(r=>r.id.startsWith('cameco'))" :key="item.id"><span>{{ item.title }} · {{ item.period }}</span><strong>{{ item.value }} <small>{{ item.unit }}</small></strong><a :href="item.source_url" target="_blank" rel="noopener noreferrer">Cameco / UxC与TradeTech月末指标 ↗</a></article></div>
      </div><div class="case-scenario"><div class="case-section-label">交付情景与库存变化</div><div class="scenario-chooser"><label for="inventory-scenario">选择交付／压力情景</label><select id="inventory-scenario" v-model="pending"><option v-for="scenario in data.scenarios" :key="scenario.id" :value="scenario.id">{{ scenario.label }}</option></select><el-button type="primary" @click="generate">生成库存曲线</el-button></div>
      <div class="plot-heading"><h3>{{ selectedScenario.label }}</h3><span>{{ selectedScenario.note }}</span></div>
      <div ref="chartElement" class="inventory-chart" role="img" aria-label="不同采购和交付情景下的每日净库存曲线"></div>
      <p class="chart-guide">负净余额表示累计未满足需求，不是物理库存；40 tU仅为12月31日期末目标。到货当日先验收入库、日末扣料，每日消耗240÷70 tU。</p>
      <div class="scenario-metrics"><div><span>首次缺口</span><strong>{{ selectedScenario.first_shortage || '无' }}</strong></div><div><span>最大累计缺口</span><strong>{{ number(selectedScenario.maximum_gap) }}<small> tU</small></strong></div><div><span>最低净余额</span><strong>{{ number(selectedScenario.minimum_balance) }}<small> tU</small></strong></div><div><span>期末净余额</span><strong>{{ number(selectedScenario.closing_balance) }}<small> tU</small></strong></div><div><span>报价变动试算指数</span><strong>{{ number(selectedScenario.price_cost_index,0) }}</strong></div></div>
      <p class="price-note">100／110／120仅表示基准报价变动0%／10%／20%的敏感性坐标，不是实际成交成本或涨幅预测。公开价格指标另列，不用它替代本企业到岸报价；涨价本身不改变物料需求。</p>
      </div><div class="case-plan"><div class="sub-heading"><h3>待检验分批方案</h3><span>交期与独立应急来源须由供方及承运方确认</span></div>
      <div class="table-scroll"><table><thead><tr><th>批次</th><th>数量</th><th>签约安排</th><th>目标可用日期</th><th>不缺料临界日期*</th></tr></thead><tbody><tr v-for="plan in data.plans" :key="plan.id"><th>{{ plan.label }}</th><td>{{ plan.quantity }} tU</td><td>取得供方书面交期后确定</td><td>{{ plan.date }}</td><td>{{ plan.latest_no_shortage_date }}</td></tr></tbody></table></div>
      <p class="chart-guide">* 临界日期以其余批次按期为条件，不是建议交期；接近临界日时库存缓冲很薄。新增总量70＋60＝130 tU，已签30＋40 tU另列，不重复采购。</p>
      <details class="scenario-table"><summary>查看全部情景的定量对照</summary><div class="table-scroll"><table><thead><tr><th>情景</th><th>首次缺口</th><th>缺口天数</th><th>最大累计缺口(tU)</th><th>期末净余额(tU)</th></tr></thead><tbody><tr v-for="scenario in data.scenarios" :key="scenario.id"><th>{{ scenario.label }}</th><td>{{ scenario.first_shortage || '无' }}</td><td>{{ scenario.shortage_days }}</td><td>{{ number(scenario.maximum_gap) }}</td><td>{{ number(scenario.closing_balance) }}</td></tr></tbody></table></div></details>
      </div><div class="case-response"><div class="sub-heading"><h3>触发条件与应对措施</h3></div><div class="trigger-grid"><article v-for="trigger in data.triggers" :key="trigger.risk"><b>{{ trigger.risk }}</b><p><span>触发</span>{{ trigger.condition }}</p><p><span>措施</span>{{ trigger.action }}</p></article></div>
      <div class="decision-prose"><h3>案例决策结果</h3><p v-for="(paragraph,i) in data.report" :key="i">{{ paragraph }}</p></div>
    </div></template>
  </section>
</template>

<script setup>
import { ref,computed,nextTick,onMounted,onUnmounted } from 'vue'
import * as echarts from 'echarts'
import request from '@/utils/request'
const root=ref(null),chartElement=ref(null),data=ref(null),loading=ref(false),error=ref(''),pending=ref('staged'),selected=ref('staged')
let chart,observer,alive=true
const number=(v,p=2)=>v==null?'—':Number(v).toFixed(p)
const selectedScenario=computed(()=>data.value?.scenarios.find(s=>s.id===selected.value))
const facts=computed(()=>[{label:'剩余需求',value:240,unit:' tU'},{label:'当前可用库存',value:80,unit:' tU'},{label:'已签待到',value:70,unit:' tU'},{label:'新增净需求',value:130,unit:' tU'},{label:'日均消耗',value:number(240/70,4),unit:' tU/天'}])
async function load(){loading.value=true;error.value='';try{const response=await request({url:'/SCnet/uraniumDecision/supply-judgment-models',method:'get'});if(!alive)return;if(!response.success)throw new Error(response.message || '案例推演结果不可用');data.value={...response.data.procurement_case,report:response.data.case_models.report,public_evidence:response.data.case_models.public_evidence};data.value.triggers=data.value.triggers.map(item=>item.risk==='价格上涨'?{risk:'价格变化',condition:'实际同口径到岸报价触及企业预算上限，或替代报价明显更优',action:'依据已核验报价、交期及预算重算锁价和批次；没有企业成本与预算时不预设经济触发百分比。'}:item);await render()}catch(e){if(alive)error.value=e.message || '案例加载失败'}finally{if(alive)loading.value=false}}
async function generate(){selected.value=pending.value;await render()}
async function render(){
  await nextTick();if(!chartElement.value||!selectedScenario.value)return
  chart ||= echarts.init(chartElement.value)
  const chosen=selectedScenario.value,axis=[data.value.case.as_of,...chosen.daily.map(r=>r.date)]
  const ids=[...new Set(['no_new','one_batch','staged',selected.value])]
  const colors={no_new:'#de6570',one_batch:'#94a3b8',staged:'#2563eb'}
  const series=ids.map(id=>{const s=data.value.scenarios.find(r=>r.id===id);return{name:s.label,type:'line',smooth:false,symbol:'none',data:[80,...s.daily.map(r=>r.net_balance)],lineStyle:{width:id===selected.value?3:1.6,type:id==='no_new'?'dashed':'solid',color:colors[id] || '#8b5cf6'},itemStyle:{color:colors[id] || '#8b5cf6'}}})
  series[0].markLine={silent:true,symbol:'none',lineStyle:{type:'dashed'},data:[{yAxis:0,label:{formatter:'缺口界线'},lineStyle:{color:'#de6570'}},{yAxis:40,label:{formatter:'期末目标40（仅末日考核）'},lineStyle:{color:'#95a6bc'}}]}
  const receiptPoints=chosen.daily.filter(r=>r.receipt>0)
  const selectedSeries=series.find(row=>row.name===chosen.label)
  if(selectedSeries)selectedSeries.markPoint={symbol:'pin',symbolSize:32,itemStyle:{color:'#3b7fca'},label:{fontSize:9,formatter:p=>`+${number(p.data.receipt,0)}`},data:receiptPoints.map(r=>({coord:[r.date,r.net_balance],receipt:r.receipt}))}
  chart.setOption({animation:false,tooltip:{trigger:'axis',confine:true,valueFormatter:value=>`${number(value)} tU`},legend:{top:6,type:'scroll',textStyle:{fontSize:11}},grid:{left:67,right:38,top:56,bottom:55},
    xAxis:{type:'category',data:axis,axisLabel:{formatter:value=>value.slice(5),fontSize:10,rotate:30}},yAxis:{type:'value',name:'日末净余额（tU）',splitLine:{lineStyle:{color:'#edf1f8'}}},series},true)
  chart.resize()
}
onMounted(()=>{observer=new ResizeObserver(()=>chart?.resize());if(root.value)observer.observe(root.value);load()})
onUnmounted(()=>{alive=false;observer?.disconnect();chart?.dispose()})
</script>

